import re

def parse(lines):
    kvre = re.compile(r'^\s+(?P<key>[^:]*?\S)\s+:\s?(?P<value>.*?)\s*$')
    akre = re.compile(r'^\[\s*akm\s*=\s*(?P<akm>[^,\s]+)\s*,\s*cipher\s*=\s*(?P<cipher>[^\]\s]+)\s*\]$')
    recs = []
    rlines = []
    other = {}
    olines = []
    skip = []
    cur = None
    for i, l in enumerate(lines):
        if not l.strip():
            cur = None
            continue
        m = kvre.match(l)
        if not m:
            skip.append(i)
            continue
        k = m.group('key')
        v = m.group('value')
        if k == 'Name':
            cur = {}
            recs.append(cur)
        if cur is not None:
            target = cur
            rlines.append(i)
        else:
            target = other
            olines.append(i)
        a = akre.match(v)
        if a:
            target[k + ' akm'] = a.group('akm')
            target[k + ' cipher'] = a.group('cipher')
        else:
            target[k] = v
    keys = []
    for r in recs:
        for k in r:
            if k not in keys:
                keys.append(k)
    rows = []
    for r in recs:
        rows.append({k: r.get(k, '') for k in keys})
    blocks = []
    if rows:
        blocks.append({'name': 'interfaces', 'kind': 'table', 'lines': rlines, 'records': rows})
    if other:
        blocks.append({'name': 'hosted network', 'kind': 'kv', 'lines': olines, 'records': [other]})
    return {'blocks': blocks, 'skip': skip}
